import os

FILES = {'.github/workflows/bot_runner.yml': "name: BackYard Catering Bot Runner\n\non:\n  schedule:\n    # Run every 5 minutes (GitHub Actions minimum interval)\n    - cron: '*/5 * * * *'\n  workflow_dispatch:\n\njobs:\n  run-bot:\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout Repository\n        uses: actions/checkout@v4\n\n      - name: Set up Python 3.11\n        uses: actions/setup-python@v5\n        with:\n          python-version: '3.11'\n          cache: 'pip'\n\n      - name: Install Dependencies\n        run: |\n          python -m pip install --upgrade pip\n          pip install python-telegram-bot==20.8 aiohttp==3.9.3\n\n      - name: Download Persistent Database\n        uses: dawidd6/action-download-artifact@v3\n        with:\n          name: backyard-db\n          path: ./\n          if_no_artifact_found: warn\n\n      - name: Execute Bot Long-Polling Cycle\n        env:\n          BALE_BOT_TOKEN: ${{ secrets.BALE_BOT_TOKEN }}\n          TELEGRAM_BOT_TOKEN: ${{ secrets.TELEGRAM_BOT_TOKEN }}\n        run: |\n          python runner.py\n\n      - name: Upload Persistent Database\n        uses: actions/upload-artifact@v4\n        with:\n          name: backyard-db\n          path: backyard.db\n          retention-days: 90\n", 'config.py': '# -*- coding: utf-8 -*-\nimport os\n\nBALE_BOT_TOKEN = os.getenv("BALE_BOT_TOKEN", "1422365880:lwJ9WmGUrQ-x_OvBb2QBVmlwbugmdPJ-jU4")\nTELEGRAM_BOT_TOKEN = os.getenv("TELEGRAM_BOT_TOKEN", "8840698151:AAEbcUc5-3ymRt_skCaK9L4l3KP0QIOUtzs")\nDB_NAME = "backyard.db"\n# Github Pages or hosted WebApp URL for MiniApp\nWEBAPP_URL = os.getenv("WEBAPP_URL", "https://vahid55555.github.io/backyard-webapp/")\n', 'database.py': '# -*- coding: utf-8 -*-\nimport sqlite3\nfrom config import DB_NAME\n\nclass Database:\n    def __init__(self, db_name=DB_NAME):\n        self.db_name = db_name\n        self.init_db()\n\n    def get_connection(self):\n        conn = sqlite3.connect(self.db_name)\n        conn.row_factory = sqlite3.Row\n        return conn\n\n    def init_db(self):\n        with self.get_connection() as conn:\n            cursor = conn.cursor()\n            cursor.execute("""\n                CREATE TABLE IF NOT EXISTS users (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    platform TEXT NOT NULL,\n                    platform_user_id TEXT NOT NULL,\n                    full_name TEXT,\n                    phone TEXT,\n                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                    UNIQUE(platform, platform_user_id)\n                )\n            """)\n            cursor.execute("""\n                CREATE TABLE IF NOT EXISTS menu (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    title TEXT NOT NULL,\n                    description TEXT,\n                    price INTEGER NOT NULL,\n                    image_url TEXT,\n                    is_available INTEGER DEFAULT 1\n                )\n            """)\n            cursor.execute("""\n                CREATE TABLE IF NOT EXISTS orders (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    user_id INTEGER NOT NULL,\n                    status TEXT DEFAULT \'pending\',\n                    total_price INTEGER DEFAULT 0,\n                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                    FOREIGN KEY (user_id) REFERENCES users(id)\n                )\n            """)\n            cursor.execute("""\n                CREATE TABLE IF NOT EXISTS order_items (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    order_id INTEGER NOT NULL,\n                    menu_id INTEGER NOT NULL,\n                    quantity INTEGER DEFAULT 1,\n                    price INTEGER NOT NULL,\n                    FOREIGN KEY (order_id) REFERENCES orders(id),\n                    FOREIGN KEY (menu_id) REFERENCES menu(id)\n                )\n            """)\n            \n            cursor.execute("SELECT COUNT(*) FROM menu")\n            if cursor.fetchone()[0] == 0:\n                sample_menu = [\n                    ("چلو کباب کوبیده ممتاز", "دو سیخ کباب کوبیده ۱۲۰ گرمی + برنج ایرانی", 220000, "https://images.unsplash.com/photo-1544025162-d76694265947?w=400", 1),\n                    ("زرشک پلو با مرغ", "ران مرغ سس\u200cپز + برنج ایرانی و زرشک", 180000, "https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?w=400", 1),\n                    ("خورشت قورمه سبزی", "خورشت قورمه سبزی با گوشت گوسفندی + برنج", 160000, "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=400", 1),\n                    ("سالاد فصل", "سالاد تازه به همراه سس مخصوص", 40000, "https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=400", 1)\n                ]\n                cursor.executemany("""\n                    INSERT INTO menu (title, description, price, image_url, is_available)\n                    VALUES (?, ?, ?, ?, ?)\n                """, sample_menu)\n            conn.commit()\n', 'core/models.py': '# -*- coding: utf-8 -*-\nfrom dataclasses import dataclass\nfrom typing import Optional, List\n\n@dataclass\nclass User:\n    id: Optional[int]\n    platform: str\n    platform_user_id: str\n    full_name: str\n    phone: Optional[str] = None\n\n@dataclass\nclass MenuItem:\n    id: int\n    title: str\n    description: str\n    price: int\n    image_url: str\n    is_available: bool\n\n@dataclass\nclass OrderItem:\n    menu_id: int\n    title: str\n    quantity: int\n    price: int\n\n@dataclass\nclass Order:\n    id: Optional[int]\n    user_id: int\n    status: str\n    total_price: int\n    items: List[OrderItem]\n', 'core/manager.py': '# -*- coding: utf-8 -*-\nfrom database import Database\nfrom core.models import User, MenuItem, Order, OrderItem\n\nclass CateringManager:\n    def __init__(self):\n        self.db = Database()\n\n    def get_or_create_user(self, platform: str, platform_user_id: str, full_name: str) -> User:\n        with self.db.get_connection() as conn:\n            cursor = conn.cursor()\n            cursor.execute(\n                "SELECT id, platform, platform_user_id, full_name, phone FROM users WHERE platform = ? AND platform_user_id = ?",\n                (platform, str(platform_user_id))\n            )\n            row = cursor.fetchone()\n            if row:\n                return User(id=row["id"], platform=row["platform"], platform_user_id=row["platform_user_id"], full_name=row["full_name"], phone=row["phone"])\n            \n            cursor.execute(\n                "INSERT INTO users (platform, platform_user_id, full_name) VALUES (?, ?, ?)",\n                (platform, str(platform_user_id), full_name)\n            )\n            conn.commit()\n            return User(id=cursor.lastrowid, platform=platform, platform_user_id=str(platform_user_id), full_name=full_name)\n\n    def get_available_menu(self) -> list[MenuItem]:\n        with self.db.get_connection() as conn:\n            cursor = conn.cursor()\n            cursor.execute("SELECT id, title, description, price, image_url, is_available FROM menu WHERE is_available = 1")\n            rows = cursor.fetchall()\n            return [\n                MenuItem(\n                    id=row["id"],\n                    title=row["title"],\n                    description=row["description"],\n                    price=row["price"],\n                    image_url=row["image_url"] or "",\n                    is_available=bool(row["is_available"])\n                ) for row in rows\n            ]\n\n    def create_order(self, user_id: int, items_data: list[dict]) -> Order:\n        with self.db.get_connection() as conn:\n            cursor = conn.cursor()\n            total_price = 0\n            order_items = []\n\n            for item in items_data:\n                cursor.execute("SELECT title, price FROM menu WHERE id = ?", (item[\'menu_id\'],))\n                menu_row = cursor.fetchone()\n                if menu_row:\n                    price = menu_row[\'price\']\n                    qty = item[\'quantity\']\n                    total_price += price * qty\n                    order_items.append(OrderItem(menu_id=item[\'menu_id\'], title=menu_row[\'title\'], quantity=qty, price=price))\n\n            cursor.execute(\n                "INSERT INTO orders (user_id, status, total_price) VALUES (?, \'registered\', ?)",\n                (user_id, total_price)\n            )\n            order_id = cursor.lastrowid\n\n            for oi in order_items:\n                cursor.execute(\n                    "INSERT INTO order_items (order_id, menu_id, quantity, price) VALUES (?, ?, ?, ?)",\n                    (order_id, oi.menu_id, oi.quantity, oi.price)\n                )\n\n            conn.commit()\n            return Order(id=order_id, user_id=user_id, status=\'registered\', total_price=total_price, items=order_items)\n', 'adapters/__init__.py': '', 'core/__init__.py': '', 'adapters/base.py': '# -*- coding: utf-8 -*-\nfrom abc import ABC, abstractmethod\n\nclass BaseAdapter(ABC):\n    @abstractmethod\n    async def run_batch(self, timeout_seconds: int = 240):\n        pass\n', 'adapters/bale_bot.py': '# -*- coding: utf-8 -*-\nimport asyncio\nimport logging\nimport time\nimport aiohttp\nfrom adapters.base import BaseAdapter\nfrom core.manager import CateringManager\n\nlogger = logging.getLogger("BaleAdapter")\n\nclass BaleAdapter(BaseAdapter):\n    def __init__(self, token: str):\n        self.token = token\n        self.api_url = f"https://tapi.bale.ai/bot{self.token}"\n        self.manager = CateringManager()\n        self.offset = 0\n\n    async def send_message(self, session, chat_id: int, text: str):\n        url = f"{self.api_url}/sendMessage"\n        payload = {"chat_id": chat_id, "text": text}\n        try:\n            async with session.post(url, json=payload) as resp:\n                return await resp.json()\n        except Exception as e:\n            logger.error(f"Error sending message in Bale: {e}")\n\n    async def handle_update(self, session, update: dict):\n        message = update.get("message", {})\n        chat_id = message.get("chat", {}).get("id")\n        text = message.get("text", "")\n        from_user = message.get("from", {})\n\n        if not chat_id or not text:\n            return\n\n        user = self.manager.get_or_create_user(\n            platform="bale",\n            platform_user_id=str(from_user.get("id")),\n            full_name=f"{from_user.get(\'first_name\', \'\')} {from_user.get(\'last_name\', \'\')}".strip()\n        )\n\n        if text == "/start":\n            welcome_text = (\n                f"سلام {user.full_name} عزیز! 👋\\n"\n                "به کترینگ «حیاط پشتی» خوش آمدید.\\n\\n"\n                "📋 /menu - مشاهده لیست غذاها\\n"\n                "🛒 جهت ثبت سفارش: order [کد_غذا] [تعداد]"\n            )\n            await self.send_message(session, chat_id, welcome_text)\n\n        elif text == "/menu":\n            items = self.manager.get_available_menu()\n            if not items:\n                await self.send_message(session, chat_id, "منویی فعال نیست.")\n                return\n\n            menu_text = "🍽 **منوی روز کترینگ حیاط پشتی:**\\n\\n"\n            for item in items:\n                menu_text += f"🔹 **{item.title}** (کد: {item.id})\\n"\n                menu_text += f"   توضیحات: {item.description}\\n"\n                menu_text += f"   قیمت: {item.price:,} تومان\\n\\n"\n            await self.send_message(session, chat_id, menu_text)\n\n        elif text.startswith("order"):\n            try:\n                parts = text.split()\n                menu_id = int(parts[1])\n                qty = int(parts[2]) if len(parts) > 2 else 1\n                \n                order = self.manager.create_order(user.id, [{\'menu_id\': menu_id, \'quantity\': qty}])\n                res_text = (\n                    f"✅ **سفارش شما با موفقیت ثبت شد!**\\n"\n                    f"شماره سفارش: #{order.id}\\n"\n                    f"مبلغ کل: {order.total_price:,} تومان"\n                )\n                await self.send_message(session, chat_id, res_text)\n            except Exception:\n                await self.send_message(session, chat_id, "فرمت نادرست. مثال: order 1 2")\n\n    async def run_batch(self, timeout_seconds: int = 240):\n        start_time = time.time()\n        logger.info("Bale Bot Adapter batch started...")\n        async with aiohttp.ClientSession() as session:\n            while time.time() - start_time < timeout_seconds:\n                try:\n                    url = f"{self.api_url}/getUpdates?offset={self.offset}&timeout=10"\n                    async with session.get(url, timeout=15) as resp:\n                        if resp.status == 200:\n                            data = await resp.json()\n                            if data.get("ok"):\n                                for update in data.get("result", []):\n                                    self.offset = update["update_id"] + 1\n                                    await self.handle_update(session, update)\n                except Exception as e:\n                    logger.error(f"Error in Bale Polling: {e}")\n                    await asyncio.sleep(3)\n', 'adapters/telegram_bot.py': '# -*- coding: utf-8 -*-\nimport logging\nimport time\nimport asyncio\nfrom telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup, WebAppInfo\nfrom telegram.ext import Application, CommandHandler, ContextTypes\nfrom adapters.base import BaseAdapter\nfrom core.manager import CateringManager\nfrom config import WEBAPP_URL\n\nlogger = logging.getLogger("TelegramAdapter")\n\nclass TelegramAdapter(BaseAdapter):\n    def __init__(self, token: str):\n        self.token = token\n        self.manager = CateringManager()\n\n    async def start_cmd(self, update: Update, context: ContextTypes.DEFAULT_TYPE):\n        tg_user = update.effective_user\n        user = self.manager.get_or_create_user(\n            platform="telegram",\n            platform_user_id=str(tg_user.id),\n            full_name=tg_user.full_name\n        )\n        \n        keyboard = [\n            [InlineKeyboardButton("🍽 باز کردن مینی اپ منو و سفارش", web_app=WebAppInfo(url=WEBAPP_URL))]\n        ]\n        reply_markup = InlineKeyboardMarkup(keyboard)\n\n        welcome_text = (\n            f"سلام {user.full_name} عزیز! 👋\\n"\n            "به **کترینگ حیاط پشتی** خوش آمدید.\\n\\n"\n            "برای مشاهده کاتالوگ تصویری و ثبت سفارش آنلاین، روی دکمه زیر کلیک کنید:"\n        )\n        await update.message.reply_text(welcome_text, reply_markup=reply_markup, parse_mode="Markdown")\n\n    async def menu_cmd(self, update: Update, context: ContextTypes.DEFAULT_TYPE):\n        items = self.manager.get_available_menu()\n        if not items:\n            await update.message.reply_text("در حال حاضر منویی فعال نیست.")\n            return\n\n        menu_text = "🍽 **منوی روز کترینگ حیاط پشتی:**\\n\\n"\n        for item in items:\n            menu_text += f"🔹 **{item.title}** (کد: `{item.id}`)\\n"\n            menu_text += f"   قیمت: {item.price:,} تومان\\n\\n"\n            \n        keyboard = [[InlineKeyboardButton("🛍 سفارش در مینی\u200cاپ", web_app=WebAppInfo(url=WEBAPP_URL))]]\n        await update.message.reply_text(menu_text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode="Markdown")\n\n    async def run_batch(self, timeout_seconds: int = 240):\n        logger.info("Telegram Bot Adapter batch starting...")\n        app = Application.builder().token(self.token).build()\n        app.add_handler(CommandHandler("start", self.start_cmd))\n        app.add_handler(CommandHandler("menu", self.menu_cmd))\n\n        await app.initialize()\n        await app.start()\n        await app.updater.start_polling(drop_pending_updates=False)\n\n        # Run for specified duration in GitHub Actions\n        await asyncio.sleep(timeout_seconds)\n\n        await app.updater.stop()\n        await app.stop()\n        await app.shutdown()\n', 'webapp/index.html': '<!DOCTYPE html>\n<html lang="fa" dir="rtl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>کترینگ حیاط پشتی | سفارش آنلاین</title>\n    <script src="https://telegram.org/js/telegram-web-app.js"></script>\n    <script src="https://cdn.tailwindcss.com"></script>\n    <style>\n        body { font-family: system-ui, -apple-system, sans-serif; background-color: var(--tg-theme-bg-color, #f9fafb); color: var(--tg-theme-text-color, #111827); }\n    </style>\n</head>\n<body class="p-4 pb-20">\n    <header class="mb-6 text-center">\n        <h1 class="text-2xl font-bold text-amber-600">🍽 کترینگ حیاط پشتی</h1>\n        <p class="text-sm text-gray-500 mt-1">سفارش آنلاین و سریع انواع غذاهای ایرانی</p>\n    </header>\n\n    <div id="menu-container" class="space-y-4">\n        <!-- Menu Items dynamically rendered -->\n        <div class="bg-white rounded-xl shadow-sm border p-3 flex gap-3 items-center">\n            <img src="https://images.unsplash.com/photo-1544025162-d76694265947?w=150" class="w-20 h-20 rounded-lg object-cover">\n            <div class="flex-1">\n                <h3 class="font-bold text-base">چلو کباب کوبیده ممتاز</h3>\n                <p class="text-xs text-gray-500 mt-1">دو سیخ کباب کوبیده ۱۲۰ گرمی + برنج ایرانی</p>\n                <div class="mt-2 flex justify-between items-center">\n                    <span class="text-amber-700 font-extrabold text-sm">۲۲۰,۰۰۰ تومان</span>\n                    <button onclick="addToCart(1, \'چلو کباب کوبیده ممتاز\', 220000)" class="bg-amber-500 hover:bg-amber-600 text-white text-xs px-3 py-1.5 rounded-lg">افزودن</button>\n                </div>\n            </div>\n        </div>\n\n        <div class="bg-white rounded-xl shadow-sm border p-3 flex gap-3 items-center">\n            <img src="https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?w=150" class="w-20 h-20 rounded-lg object-cover">\n            <div class="flex-1">\n                <h3 class="font-bold text-base">زرشک پلو با مرغ</h3>\n                <p class="text-xs text-gray-500 mt-1">ران مرغ سس\u200cپز + برنج ایرانی و زرشک</p>\n                <div class="mt-2 flex justify-between items-center">\n                    <span class="text-amber-700 font-extrabold text-sm">۱۸۰,۰۰۰ تومان</span>\n                    <button onclick="addToCart(2, \'زرشک پلو با مرغ\', 180000)" class="bg-amber-500 hover:bg-amber-600 text-white text-xs px-3 py-1.5 rounded-lg">افزودن</button>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- Sticky Cart Summary Footer -->\n    <div class="fixed bottom-0 left-0 right-0 bg-white border-t p-3 flex justify-between items-center shadow-lg">\n        <div>\n            <span class="text-xs text-gray-500 block">جمع کل:</span>\n            <span id="total-price" class="text-lg font-black text-amber-600">۰ تومان</span>\n        </div>\n        <button onclick="submitOrder()" class="bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2.5 rounded-xl font-bold text-sm">تکمیل سفارش</button>\n    </div>\n\n    <script>\n        const tg = window.Telegram.WebApp;\n        tg.expand();\n\n        let cart = {};\n\n        function addToCart(id, title, price) {\n            if (cart[id]) {\n                cart[id].qty += 1;\n            } else {\n                cart[id] = { title, price, qty: 1 };\n            }\n            updateUI();\n        }\n\n        function updateUI() {\n            let total = 0;\n            for (let id in cart) {\n                total += cart[id].price * cart[id].qty;\n            }\n            document.getElementById(\'total-price\').innerText = total.toLocaleString(\'fa-IR\') + \' تومان\';\n        }\n\n        function submitOrder() {\n            if (Object.keys(cart).length === 0) {\n                alert(\'سبد خرید شما خالی است!\');\n                return;\n            }\n            const orderData = {\n                action: "submit_order",\n                items: cart\n            };\n            tg.sendData(JSON.stringify(orderData));\n            tg.close();\n        }\n    </script>\n</body>\n</html>\n', 'runner.py': '# -*- coding: utf-8 -*-\nimport asyncio\nimport logging\nfrom config import BALE_BOT_TOKEN, TELEGRAM_BOT_TOKEN\nfrom adapters.bale_bot import BaleAdapter\nfrom adapters.telegram_bot import TelegramAdapter\n\nlogging.basicConfig(level=logging.INFO)\n\nasync def main():\n    print("=== شروع سیکل پردازش GitHub Actions کترینگ حیاط پشتی ===")\n    bale_adapter = BaleAdapter(token=BALE_BOT_TOKEN)\n    telegram_adapter = TelegramAdapter(token=TELEGRAM_BOT_TOKEN)\n\n    # Run polling for 4 minutes (240s) within the GitHub Actions runner execution cycle\n    await asyncio.gather(\n        bale_adapter.run_batch(timeout_seconds=240),\n        telegram_adapter.run_batch(timeout_seconds=240)\n    )\n    print("=== پایان سیکل پردازش و ذخیره\u200cسازی داده\u200cها ===")\n\nif __name__ == "__main__":\n    asyncio.run(main())\n'}

def setup():
    for path, content in FILES.items():
        dir_name = os.path.dirname(path)
        if dir_name and not os.path.exists(dir_name):
            os.makedirs(dir_name, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[+] Created file: {path}")
    print("\n✅ تمام فایل‌ها و زیرساخت GitHub Actions با موفقیت ایجاد شدند.")

if __name__ == "__main__":
    setup()
